/**
 * The ground of the page, as data: the contour lines of four hills along the edges of the window,
 * the route that runs between them, and the two small hills and the long lines of a telephone
 * (owner, 14.11.2026, PDL „Vizuelno osveženje „Race in Motion"", and the approved draft of
 * 20.11.2026, `btl-produkt/predlozi/plan-dodaci-naslovne.html`, section „Pozadina i tačka").
 *
 * GENERATED ONCE FROM FIXED NUMBERS AND WRITTEN DOWN, never drawn by hand and never random: no
 * line here is computed when the page runs, so two readers see the same hills. Each contour is its
 * own shape (the lines of one hill are not copies of one another), and each carries the strength
 * its place in the hill gives it, from 0,45 on the outermost line to 1 on the innermost; the
 * colour is the sheet's (`--race-contour`), so no line here is stronger than the token says.
 *
 * The coordinates are in the drawing's own units (`DESKTOP_VIEW` and `PHONE_VIEW`), cut to the
 * window with `slice`, so the hills stay at the edges whatever the proportions of the window. Some
 * of the lines run past the box of the drawing on purpose: the window cuts them, which is how a
 * hill is seen to go on beyond the edge.
 */

export interface Contour {
  /** The outline, as an SVG path. */
  d: string
  /** The strength of this line against the colour of the token, 0 to 1. */
  opacity: number
}

/** The box the desktop drawing is laid out in. */
export const DESKTOP_VIEW = '0 0 1600 1000'

/** The box the telephone drawing is laid out in. */
export const PHONE_VIEW = '0 0 360 800'

